 diagram:{name:'Cell Structures',icon:'🧬',mode:'CLASS',input:'diagram',subjects:['biology'],rule:'Choose an animal or plant cell, then Easy, Medium or Hard. Tap the numbered structure that matches each prompt, then study the picture and explanation. Teachers can also upload a custom diagram.'},
 crossword:{name:'Crossword',icon:'🧩',input:'word',subjects:['english'],rule:'Select a numbered clue and type its word. Correct answers fill the crossing letters. Solve every clue.'},
